import{_ as r,C as o,o as e,c as n,a2 as l,b as s,w as d,a as i,E as g,a3 as c}from"./chunks/framework.BBdhqAg0.js";const E="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",_=JSON.parse('{"title":"수수료 지급 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/payout.md","filePath":"sales/payout.md","lastUpdated":1793110703000}'),C={name:"sales/payout.md"};function B(x,t,A,y,f,h){const a=o("Mermaid");return e(),n("div",null,[t[1]||(t[1]=l('<h1 id="수수료-지급-관리" tabindex="-1">수수료 지급 관리 <a class="header-anchor" href="#수수료-지급-관리" aria-label="Permalink to &quot;수수료 지급 관리&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+E+'" alt="수수료 지급 진행 현황 및 은행 이체 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/payout.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>수수료 지급 관리</strong> 페이지는 확정된 정산 내역을 바탕으로 금융 이체 승인, 기업 인터넷 뱅킹 대량 이체 파일(CSV) 다운로드, 그리고 지급 완료 및 보류 처리를 일괄/개별 관리하는 자금 집행 센터입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [분양 대행 관리] → [수수료 지급 관리]**를 선택하여 접속합니다.</li></ul>',4)),(e(),s(c,null,{default:d(()=>[g(a,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%ED%99%95%EC%A0%95%20%ED%9A%8C%EC%B0%A8%20%EC%A1%B0%ED%9A%8C%3Cbr%3E(%EC%A0%95%EC%82%B0%20%EC%99%84%EB%A3%8C%20%EB%82%B4%EC%97%AD%20%EB%A1%9C%EB%93%9C)%22%5D%20--%3E%20B%5B%222.%20%EB%8C%80%EB%9F%89%20%EC%9D%B4%EC%B2%B4%20CSV%20%EB%8B%A4%EC%9A%B4%EB%A1%9C%EB%93%9C%3Cbr%3E(%EA%B8%B0%EC%97%85%20%EB%B1%85%ED%82%B9%20%ED%91%9C%EC%A4%80%20%EC%84%9C%EC%8B%9D)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EC%9D%B8%ED%84%B0%EB%84%B7%20%EB%B1%85%ED%82%B9%20%EC%9D%B4%EC%B2%B4%20%EC%8B%A4%ED%96%89%3Cbr%3E(%EC%9D%80%ED%96%89%20%EB%8C%80%EB%9F%89%20%EC%9D%B4%EC%B2%B4%20%EC%97%85%EB%A1%9C%EB%93%9C)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%84%A0%ED%83%9D%20%EC%A7%80%EA%B8%89%EC%99%84%EB%A3%8C%20%EC%9D%BC%EA%B4%84%20%EC%B2%98%EB%A6%AC%3Cbr%3E(%EC%9D%B4%EC%B2%B4%20%EC%99%84%EB%A3%8C%EC%9D%BC%20%EC%9E%90%EB%8F%99%20%EA%B0%81%EC%9D%B8)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%F0%9F%8F%9B%EF%B8%8F%20%EC%9D%B5%EC%9B%94%2010%EC%9D%BC%20%EC%9B%90%EC%B2%9C%EC%84%B8%20%EC%8B%A0%EA%B3%A0%3Cbr%3E(3.3%25%20%EC%98%88%EC%88%98%EA%B8%88%20%EC%84%B8%EB%AC%B4%20%EB%82%A9%EB%B6%80)%22%5D%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_1-개요-및-주요-기능" tabindex="-1">1. 개요 및 주요 기능 <a class="header-anchor" href="#_1-개요-및-주요-기능" aria-label="Permalink to &quot;1. 개요 및 주요 기능&quot;">​</a></h2><p>정산이 최종 확정된 수수료에 대해 실제 금융 이체와 자금 집행을 총괄하는 화면입니다.</p><ul><li><strong>지급 진척도 실시간 모니터링</strong>: 전체 실지급 대상액과 현재까지의 이체 완료액, 진행률(%)을 실시간으로 추적합니다.</li><li><strong>원천세 예수금(3.3%) 사전 파악</strong>: 익월 10일 세무서 및 구청에 신고·납부해야 할 소득세(3%) 및 지방소득세(0.3%) 예수금 합계를 사전에 파악하여 세무 리스크를 방지합니다.</li><li><strong>기업 인터넷 뱅킹 대량 이체용 CSV 다운로드</strong>: <ul><li>엑셀에서 바로 열어도 한글이 깨지지 않도록 표준 인코딩(UTF-8 BOM)을 적용했습니다.</li><li>계좌번호 앞자리 &#39;0&#39; 유실 및 지수 표기(예: <code>1.23E+11</code>) 방지 서식을 적용하여 안전한 이체를 지원합니다.</li></ul></li><li><strong>다중 선택 기반 일괄 상태 변경</strong>: 체크박스로 여러 명을 선택하여 <code>[선택 승인]</code>, <code>[선택 지급완료]</code>, <code>[선택 지급보류]</code>를 원클릭으로 처리할 수 있습니다.</li></ul><h2 id="_2-화면-구성-및-조작-가이드" tabindex="-1">2. 화면 구성 및 조작 가이드 <a class="header-anchor" href="#_2-화면-구성-및-조작-가이드" aria-label="Permalink to &quot;2. 화면 구성 및 조작 가이드&quot;">​</a></h2><h3 id="_1-회차-선택-및-필터-툴바" tabindex="-1">1. 회차 선택 및 필터 툴바 <a class="header-anchor" href="#_1-회차-선택-및-필터-툴바" aria-label="Permalink to &quot;1. 회차 선택 및 필터 툴바&quot;">​</a></h3><ul><li><strong>정산 회차 선택</strong>: 지급을 진행할 정산 회차 선택</li><li><strong>지급 상태 필터</strong>: <code>전체</code>, <code>지급대기</code>, <code>지급승인</code>, <code>지급완료</code>, <code>지급보류</code></li><li><strong>통합 검색창</strong>: 성명, 소속 팀, 예금주, 계좌번호로 실시간 검색</li><li><strong>조회 건수 표출</strong>: 필터 조건에 부합하는 대상 인원수 표시</li></ul><h3 id="_2-지급-진행-현황-대시보드-상단-요약-카드" tabindex="-1">2. 지급 진행 현황 대시보드 (상단 요약 카드) <a class="header-anchor" href="#_2-지급-진행-현황-대시보드-상단-요약-카드" aria-label="Permalink to &quot;2. 지급 진행 현황 대시보드 (상단 요약 카드)&quot;">​</a></h3><ul><li><strong>총 실지급 대상액 (세후)</strong>: 이번 회차에 집행되어야 할 총 이체 대상 금액</li><li><strong>지급 완료액 (이체완료)</strong>: 이미 지급 완료 처리된 금액과 전체 대비 진척률(%)</li><li><strong>지급 잔액 (대기/보류)</strong>: 아직 이체되지 않고 남아있는 잔액과 대기 인원수</li><li><strong>원천세 예수금 합계 (3.3%)</strong>: 회사가 원천징수하여 다음 달 10일에 국세청(소득세 3%) 및 지자체(지방소득세 0.3%)에 납부해야 할 세액 총액</li></ul><h3 id="_3-일괄-작업-및-이체-파일-다운로드-액션-바" tabindex="-1">3. 일괄 작업 및 이체 파일 다운로드 액션 바 <a class="header-anchor" href="#_3-일괄-작업-및-이체-파일-다운로드-액션-바" aria-label="Permalink to &quot;3. 일괄 작업 및 이체 파일 다운로드 액션 바&quot;">​</a></h3><ul><li><strong>전체 선택 체크박스</strong>: 현재 필터링된 모든 항목을 일괄 선택하거나 해제</li><li><strong>선택 정보 배지</strong>: 현재 선택된 인원수와 세후 실지급 합계 금액을 실시간 계산하여 표출</li><li><strong>일괄 상태 변경 버튼군</strong>: <ul><li><strong><code>[선택 승인]</code></strong>: 선택된 인력들의 상태를 <code>지급승인</code>으로 일괄 변경</li><li><strong><code>[선택 지급완료]</code></strong>: 이체가 완료된 후 선택된 인력들의 상태를 <code>지급완료</code>로 변경 (오늘 날짜가 지급일로 자동 각인)</li><li><strong><code>[선택 지급보류]</code></strong>: 계좌 오류나 서류 미제출 등으로 이체를 보류할 때 지정</li><li><strong><code>[선택 해제]</code></strong>: 선택 상태 초기화</li></ul></li><li><strong>[은행 이체용 CSV 다운로드] 버튼</strong>: 기업 뱅킹 대량 이체 표준 규격에 맞춘 CSV 파일 다운로드</li></ul><h3 id="_4-지급-명세-테이블" tabindex="-1">4. 지급 명세 테이블 <a class="header-anchor" href="#_4-지급-명세-테이블" aria-label="Permalink to &quot;4. 지급 명세 테이블&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>선택 체크박스</strong></td><td style="text-align:left;">일괄 상태 변경 또는 선별 이체 다운로드를 위한 체크박스</td></tr><tr><td style="text-align:left;"><strong>소속 팀 / 직책 / 성명</strong></td><td style="text-align:left;">영업 인력의 인적 정보</td></tr><tr><td style="text-align:left;"><strong>은행명 / 계좌번호 / 예금주</strong></td><td style="text-align:left;">수수료가 입금될 금융 계좌 정보</td></tr><tr><td style="text-align:left;"><strong>총액 (세전)</strong></td><td style="text-align:left;">정산된 세전 총액</td></tr><tr><td style="text-align:left;"><strong>원천세 (3.3%)</strong></td><td style="text-align:left;">공제되는 원천징수 세액</td></tr><tr><td style="text-align:left;"><strong>실지급액 (세후)</strong></td><td style="text-align:left;">통장에 실제 입금될 금액 (굵은 글씨 강조)</td></tr><tr><td style="text-align:left;"><strong>지급 상태</strong></td><td style="text-align:left;">드롭다운 셀렉터로 즉시 상태 변경 가능 (<code>지급대기</code>, <code>지급승인</code>, <code>지급완료</code>, <code>지급보류</code>)</td></tr><tr><td style="text-align:left;"><strong>상세</strong></td><td style="text-align:left;"><code>[내역]</code> 버튼 클릭 시 개인별 상세 계약 내역 팝업 호출</td></tr></tbody></table><h3 id="_5-은행-대량-이체용-csv-규격-안내" tabindex="-1">5. 은행 대량 이체용 CSV 규격 안내 <a class="header-anchor" href="#_5-은행-대량-이체용-csv-규격-안내" aria-label="Permalink to &quot;5. 은행 대량 이체용 CSV 규격 안내&quot;">​</a></h3><p>다운로드되는 CSV 파일은 기업 뱅킹 사이트의 &#39;대량 이체 / 급여 이체&#39; 업로드 양식에 부합하도록 구성되어 있습니다:</p><table tabindex="0"><thead><tr><th style="text-align:center;">열 순번</th><th style="text-align:left;">항목명</th><th style="text-align:left;">상세 설명 및 포맷</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;">순번</td><td style="text-align:left;">1부터 시작하는 일련번호</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;">입금은행</td><td style="text-align:left;">예: 국민은행, 신한은행, 우리은행, 하나은행 등</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;">입금계좌번호</td><td style="text-align:left;">하이픈 포함 계좌번호 (지수 변환 방지 텍스트 서식 적용)</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;">예금주</td><td style="text-align:left;">수취인 예금주명</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;">실지급액 (세후)</td><td style="text-align:left;">순수 이체 대상 금액 (숫자)</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;">세전총액</td><td style="text-align:left;">원천세 공제 전 총액</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;">원천세 (3.3%)</td><td style="text-align:left;">공제 세액 합계</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;">성명</td><td style="text-align:left;">영업 인력 성명</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;">소속팀</td><td style="text-align:left;">영업 본부 및 팀명</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;">직책</td><td style="text-align:left;">상담사, 팀장, 본부장 등</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;">지급상태</td><td style="text-align:left;">지급완료, 지급승인 등</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;">지급일자</td><td style="text-align:left;">YYYY-MM-DD 포맷</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;">정산회차</td><td style="text-align:left;">회차 명칭</td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;">비고/메모</td><td style="text-align:left;">특이사항</td></tr></tbody></table><h2 id="_3-신입사원을-위한-실무-가이드" tabindex="-1">3. 신입사원을 위한 실무 가이드 <a class="header-anchor" href="#_3-신입사원을-위한-실무-가이드" aria-label="Permalink to &quot;3. 신입사원을 위한 실무 가이드&quot;">​</a></h2><ul><li><strong>💡 금융 이체 실무 3단계 요령</strong>: <ol><li><code>[수수료 지급 관리]</code> 화면에서 회차를 선택하고, 계좌 오류자가 없는지 검토한 후 **[은행 이체용 CSV 다운로드]**를 클릭합니다.</li><li>회사 거래 은행의 기업 인터넷 뱅킹에 로그인하여 <code>[대량/급여 이체]</code> 메뉴에 해당 CSV 파일을 업로드하고 비밀번호 및 OTP를 인증하여 이체를 실행합니다.</li><li>이체가 정상 완료되면 시스템으로 돌아와 전체 선택 후 <strong><code>[선택 지급완료]</code></strong> 버튼을 눌러 상태를 업데이트합니다.</li></ol></li><li><strong>💡 세무 신고 연계 팁 (원천세 3.3%)</strong>: <ul><li>화면 상단 요약 카드의 **&#39;원천세 예수금 합계(3.3%)&#39;**는 이번 달에 상담사들에게 지급하면서 원천징수한 세금 총액입니다. 회계팀 또는 세무대리인에게 전달하여 <strong>익월 10일까지 홈택스(국세 3%) 및 위택스(지방세 0.3%)에 원천세 신고 및 납부</strong>를 완료하도록 안내하십시오.</li></ul></li></ul>',17))])}const b=r(C,[["render",B]]);export{_ as __pageData,b as default};
